    public static function get_options(): array {
        $opts = get_option(AIBLOGGER_OPT_KEY, []);
        if (!is_array($opts)) $opts = [];
        $opts = wp_parse_args($opts, self::defaults());

        // Limpieza retro-compat: eliminamos opciones antiguas ya no usadas.
        if (isset($opts['external_links_custom'])) {
            unset($opts['external_links_custom']);
        }

        // Comportamientos implÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­citos (no configurables).
        $opts['optimize_images'] = 1;
        $opts['reuse_existing_terms'] = 1;
        $opts['allow_create_new_tags'] = 1;
        $opts['seo_integrations'] = 1;
        $opts['enable_metrics'] = 1;
        $opts['open_editor_new_tab'] = 1;
        $opts['tokens_daily_limit'] = max(0, (int)($opts['tokens_daily_limit'] ?? 0));
        $opts['tokens_monthly_limit'] = max(0, (int)($opts['tokens_monthly_limit'] ?? 0));
        $opts['tokens_limit_mode'] = in_array((string)($opts['tokens_limit_mode'] ?? 'warn'), ['warn', 'block'], true)
            ? (string)$opts['tokens_limit_mode']
            : 'warn';

        return $opts;
    }

    public static function update_options(array $new): void {
        $opts = wp_parse_args($new, self::get_options());
        update_option(AIBLOGGER_OPT_KEY, $opts);
    }

    public static function sanitize_options($input): array {
        $defaults = self::defaults();
        $out = [];

        $out['api_key'] = isset($input['api_key']) ? sanitize_text_field($input['api_key']) : '';

