    public static function normalize_urls(string $raw): array {
        $lines = preg_split('/\r\n|\r|\n/', (string)$raw);
        $urls = [];
        foreach ($lines as $line) {
            $u = trim((string)$line);
            if (!$u) continue;
            $u = esc_url_raw($u);
            if (!$u) continue;
            $urls[] = $u;
        }
        $urls = array_values(array_unique($urls));
        return array_slice($urls, 0, 10);
    }

