    public static function guess_mime_from_bytes(string $bytes): string {
        if (substr($bytes, 1, 3) === 'PNG') return 'image/png';
        if (substr($bytes, 0, 3) === "\xFF\xD8\xFF") return 'image/jpeg';
        if (substr($bytes, 0, 4) === 'RIFF' && substr($bytes, 8, 4) === 'WEBP') return 'image/webp';
        return 'image/png';
    }

