    /**
     * Normaliza UsageMetadata (Gemini / Vertex) a un shape estable.
     */
    public static function normalize_usage(array $usage): array {
        $get = function(array $u, array $keys, int $default = 0): int {
            foreach ($keys as $k) {
                if (isset($u[$k]) && is_numeric($u[$k])) return (int)$u[$k];
            }
            return $default;
        };

        $out = [
            'prompt_tokens'  => $get($usage, ['promptTokenCount','prompt_token_count','prompt_tokens']),
            'output_tokens'  => $get($usage, ['candidatesTokenCount','candidates_token_count','output_tokens','completion_tokens']),
            'total_tokens'   => $get($usage, ['totalTokenCount','total_token_count','total_tokens']),
            'tool_tokens'    => $get($usage, ['toolUsePromptTokenCount','tool_use_prompt_token_count','tool_tokens']),
            'thought_tokens' => $get($usage, ['thoughtsTokenCount','thoughts_token_count','thought_tokens']),
            'cached_tokens'  => $get($usage, ['cachedContentTokenCount','cached_content_token_count','cached_tokens']),
            'prompt_tokens_details' => isset($usage['promptTokensDetails']) ? $usage['promptTokensDetails'] : ($usage['prompt_tokens_details'] ?? null),
            'candidates_tokens_details' => isset($usage['candidatesTokensDetails']) ? $usage['candidatesTokensDetails'] : ($usage['candidates_tokens_details'] ?? null),
            'tool_use_prompt_tokens_details' => isset($usage['toolUsePromptTokensDetails']) ? $usage['toolUsePromptTokensDetails'] : ($usage['tool_use_prompt_tokens_details'] ?? null),
            'cache_tokens_details' => isset($usage['cacheTokensDetails']) ? $usage['cacheTokensDetails'] : ($usage['cache_tokens_details'] ?? null),
        ];

        if ((int)$out['total_tokens'] <= 0) {
            $out['total_tokens'] = (int)$out['prompt_tokens'] + (int)$out['output_tokens'] + (int)$out['tool_tokens'] + (int)$out['thought_tokens'];
        }

        return $out;
    }

    public static function aggregate_usage(array $calls): array {
        $tot = [
            'prompt_tokens' => 0,
            'output_tokens' => 0,
            'total_tokens' => 0,
            'tool_tokens' => 0,
            'thought_tokens' => 0,
            'cached_tokens' => 0,
        ];

        foreach ($calls as $c) {
            $u = $c['usage'] ?? [];
            if (!is_array($u)) continue;
            foreach ($tot as $k => $v) {
                $tot[$k] += (int)($u[$k] ?? 0);
            }
        }

        // Si el API ya devolviÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³ totalTokenCount, la suma puede no calzar (p.ej. incluye tool/thought).
        // Priorizamos consistencia: recalculamos total si viene en 0.
        if ((int)$tot['total_tokens'] <= 0) {
            $tot['total_tokens'] = (int)$tot['prompt_tokens'] + (int)$tot['output_tokens'] + (int)$tot['tool_tokens'] + (int)$tot['thought_tokens'];
        }

        return $tot;
    }

    /**
     * Suma usage ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âºnicamente para un subconjunto de tipos de llamada.
     *
     * @param array $calls  Lista de calls: [ ['type'=>..., 'usage'=>...], ... ]
     * @param array $types  Tipos a incluir (p.ej. ['text'], ['image']).
     */
    public static function aggregate_usage_for_types(array $calls, array $types): array {
        $types = array_values(array_filter(array_map('strval', $types)));
        if (!$types) return self::aggregate_usage([]);

        $filtered = [];
        foreach ($calls as $c) {
            if (!is_array($c)) continue;
            $t = (string)($c['type'] ?? '');
            if ($t && in_array($t, $types, true)) {
                $filtered[] = $c;
            }
        }
        return self::aggregate_usage($filtered);
    }

    /**
     * Suma usage para tipos que NO estÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©n en $exclude_types.
     */
    public static function aggregate_usage_excluding_types(array $calls, array $exclude_types): array {
        $exclude_types = array_values(array_filter(array_map('strval', $exclude_types)));

        $filtered = [];
        foreach ($calls as $c) {
            if (!is_array($c)) continue;
            $t = (string)($c['type'] ?? '');
            if ($t && in_array($t, $exclude_types, true)) continue;
            $filtered[] = $c;
        }
        return self::aggregate_usage($filtered);
    }

    /**
     * Breakdown estÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ndar: texto, imÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡genes y ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“extraÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â (todo lo que no sea texto/imagen).
     * ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡til para mostrar: totales texto vs totales imagen.
     */
    public static function usage_breakdown(array $calls): array {
        $text   = self::aggregate_usage_for_types($calls, ['text']);
        $images = self::aggregate_usage_for_types($calls, ['image']);
        $extra  = self::aggregate_usage_excluding_types($calls, ['text', 'image']);

        $counts = [
            'text_calls' => 0,
            'image_calls' => 0,
            'extra_calls' => 0,
        ];

        foreach ($calls as $c) {
            if (!is_array($c)) continue;
            $t = (string)($c['type'] ?? '');
            if ($t === 'text') $counts['text_calls']++;
            elseif ($t === 'image') $counts['image_calls']++;
            else $counts['extra_calls']++;
        }

        return [
            'text' => $text,
            'images' => $images,
            'extra' => $extra,
            'counts' => $counts,
        ];
    }

    public static function usage_cost_rates(): array {
        $defaults = [
            'default' => [
                'input_per_million' => 0.0,
                'output_per_million' => 0.0,
                'tool_per_million' => 0.0,
                'thought_per_million' => 0.0,
                'cached_per_million' => 0.0,
            ],
        ];
        $rates = apply_filters('aiblogger_usage_cost_rates', $defaults);
        return is_array($rates) ? $rates : $defaults;
    }

    private static function usage_cost_rate_for_model(string $model): array {
        $rates = self::usage_cost_rates();
        $model = strtolower(trim($model));

        if ($model !== '' && isset($rates[$model]) && is_array($rates[$model])) {
            return $rates[$model];
        }

        if ($model !== '') {
            foreach ($rates as $k => $v) {
                if ($k === 'default' || !is_array($v)) continue;
                $ks = strtolower(trim((string)$k));
                if ($ks !== '' && strpos($model, $ks) !== false) return $v;
            }
        }

        $def = $rates['default'] ?? [];
        return is_array($def) ? $def : [];
    }

    public static function estimate_usage_cost_usd(array $usage, string $model = ''): float {
        $u = self::normalize_usage($usage);
        $rate = self::usage_cost_rate_for_model($model);

        $input = (float)($rate['input_per_million'] ?? 0);
        $output = (float)($rate['output_per_million'] ?? 0);
        $tool = (float)($rate['tool_per_million'] ?? 0);
        $thought = (float)($rate['thought_per_million'] ?? 0);
        $cached = (float)($rate['cached_per_million'] ?? 0);

        $cost = 0.0;
        $cost += ((float)($u['prompt_tokens'] ?? 0) / 1000000.0) * $input;
        $cost += ((float)($u['output_tokens'] ?? 0) / 1000000.0) * $output;
        $cost += ((float)($u['tool_tokens'] ?? 0) / 1000000.0) * $tool;
        $cost += ((float)($u['thought_tokens'] ?? 0) / 1000000.0) * $thought;
        $cost += ((float)($u['cached_tokens'] ?? 0) / 1000000.0) * $cached;

        return round(max(0.0, $cost), 6);
    }

    public static function add_usage_to_post_metrics(int $post_id, array $call, array $models = []): void {
        $post_id = (int)$post_id;
        if ($post_id <= 0) return;
        if (!get_post($post_id)) return;

        $type = sanitize_key((string)($call['type'] ?? 'extra'));
        if (!in_array($type, ['text', 'image', 'extra'], true)) {
            $type = 'extra';
        }

        $label = sanitize_text_field((string)($call['label'] ?? ''));
        $model = sanitize_text_field((string)($call['model'] ?? ''));
        $usage = self::normalize_usage(is_array($call['usage'] ?? null) ? $call['usage'] : []);

        $m = get_post_meta($post_id, '_aiblogger_metrics', true);
        if (!is_array($m)) $m = [];

        $numeric_keys = [
            'prompt_tokens','output_tokens','total_tokens','tool_tokens','thought_tokens','cached_tokens',
            'text_prompt_tokens','text_output_tokens','text_total_tokens',
            'image_prompt_tokens','image_output_tokens','image_total_tokens',
            'extra_prompt_tokens','extra_output_tokens','extra_total_tokens',
            'text_calls','image_calls','extra_calls',
        ];
        foreach ($numeric_keys as $k) {
            $m[$k] = (int)($m[$k] ?? 0);
        }

        $m['prompt_tokens'] += (int)($usage['prompt_tokens'] ?? 0);
        $m['output_tokens'] += (int)($usage['output_tokens'] ?? 0);
        $m['total_tokens'] += (int)($usage['total_tokens'] ?? 0);
        $m['tool_tokens'] += (int)($usage['tool_tokens'] ?? 0);
        $m['thought_tokens'] += (int)($usage['thought_tokens'] ?? 0);
        $m['cached_tokens'] += (int)($usage['cached_tokens'] ?? 0);

        if ($type === 'text') {
            $m['text_prompt_tokens'] += (int)($usage['prompt_tokens'] ?? 0);
            $m['text_output_tokens'] += (int)($usage['output_tokens'] ?? 0);
            $m['text_total_tokens'] += (int)($usage['total_tokens'] ?? 0);
            $m['text_calls']++;
            if ($model && empty($m['text_model'])) $m['text_model'] = $model;
        } elseif ($type === 'image') {
            $m['image_prompt_tokens'] += (int)($usage['prompt_tokens'] ?? 0);
            $m['image_output_tokens'] += (int)($usage['output_tokens'] ?? 0);
            $m['image_total_tokens'] += (int)($usage['total_tokens'] ?? 0);
            $m['image_calls']++;
            if ($model && empty($m['image_model'])) $m['image_model'] = $model;
        } else {
            $m['extra_prompt_tokens'] += (int)($usage['prompt_tokens'] ?? 0);
            $m['extra_output_tokens'] += (int)($usage['output_tokens'] ?? 0);
            $m['extra_total_tokens'] += (int)($usage['total_tokens'] ?? 0);
            $m['extra_calls']++;
        }

        if (!empty($models['text_model'])) {
            $m['text_model'] = sanitize_text_field((string)$models['text_model']);
        }
        if (!empty($models['image_model'])) {
            $m['image_model'] = sanitize_text_field((string)$models['image_model']);
        }

        $entry = [
            'type' => $type,
            'label' => $label,
            'model' => $model,
            'ts' => time(),
            'usage' => [
                'prompt_tokens' => (int)($usage['prompt_tokens'] ?? 0),
                'output_tokens' => (int)($usage['output_tokens'] ?? 0),
                'total_tokens' => (int)($usage['total_tokens'] ?? 0),
                'tool_tokens' => (int)($usage['tool_tokens'] ?? 0),
                'thought_tokens' => (int)($usage['thought_tokens'] ?? 0),
                'cached_tokens' => (int)($usage['cached_tokens'] ?? 0),
            ],
        ];

        $calls = is_array($m['calls'] ?? null) ? $m['calls'] : [];
        array_unshift($calls, $entry);
        $m['calls'] = array_slice($calls, 0, 50);

        if (empty($m['generated_at'])) {
            $m['generated_at'] = time();
        }
        $m['updated_at'] = time();

        update_post_meta($post_id, '_aiblogger_metrics', $m);
    }

    // -----------------------------
    // Log global (acciones sin post)
    // -----------------------------

    public static function usage_table_name(): string {
        global $wpdb;
        return $wpdb->prefix . 'aiblogger_usage_events';
    }

    public static function ensure_usage_table(): void {
        global $wpdb;
        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $table = self::usage_table_name();
        $charset = $wpdb->get_charset_collate();

        $sql = "CREATE TABLE {$table} (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            event_ts BIGINT UNSIGNED NOT NULL,
            created_at DATETIME NOT NULL,
            label VARCHAR(191) NOT NULL DEFAULT '',
            type VARCHAR(50) NOT NULL DEFAULT 'extra',
            model VARCHAR(120) NOT NULL DEFAULT '',
            prompt_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            output_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            total_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            tool_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            thought_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            cached_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
            payload LONGTEXT NULL,
            PRIMARY KEY (id),
            KEY event_ts (event_ts),
            KEY type (type)
        ) {$charset};";

        dbDelta($sql);
    }

    private static function usage_table_ready(): bool {
        global $wpdb;
        $table = self::usage_table_name();
        $found = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
        return is_string($found) && $found === $table;
    }

    public static function migrate_usage_log_option_to_table(): void {
        if (!self::usage_table_ready()) return;

        $legacy = get_option('aiblogger_usage_log', []);
        if (!is_array($legacy) || !$legacy) return;

        global $wpdb;
        $table = self::usage_table_name();
        $count = (int)$wpdb->get_var("SELECT COUNT(*) FROM {$table}");
        if ($count > 0) return;

        foreach ($legacy as $e) {
            if (!is_array($e)) continue;
            $usage = self::normalize_usage(is_array($e['usage'] ?? null) ? $e['usage'] : []);
            $ts = (int)($e['ts'] ?? time());

            $wpdb->insert($table, [
                'event_ts' => $ts,
                'created_at' => gmdate('Y-m-d H:i:s', $ts),
                'label' => sanitize_text_field((string)($e['label'] ?? '')),
                'type' => sanitize_key((string)($e['type'] ?? 'extra')),
                'model' => sanitize_text_field((string)($e['model'] ?? '')),
                'prompt_tokens' => (int)($usage['prompt_tokens'] ?? 0),
                'output_tokens' => (int)($usage['output_tokens'] ?? 0),
                'total_tokens' => (int)($usage['total_tokens'] ?? 0),
                'tool_tokens' => (int)($usage['tool_tokens'] ?? 0),
                'thought_tokens' => (int)($usage['thought_tokens'] ?? 0),
                'cached_tokens' => (int)($usage['cached_tokens'] ?? 0),
                'payload' => wp_json_encode(['usage' => $usage]),
            ], ['%d','%s','%s','%s','%s','%d','%d','%d','%d','%d','%d','%s']);
        }

        delete_option('aiblogger_usage_log');
    }

    /**
     * Guarda un evento de uso (tokens) fuera de la generacion de posts.
     */
    public static function log_usage_event(array $event, int $keep_last = 100000): void {
        $keep_last = max(1000, min(500000, (int)$keep_last));

        $usage = [];
        if (!empty($event['usage']) && is_array($event['usage'])) {
            $usage = self::normalize_usage($event['usage']);
        }

        $entry = [
            'ts' => time(),
            'label' => sanitize_text_field((string)($event['label'] ?? '')),
            'type' => sanitize_key((string)($event['type'] ?? 'extra')),
            'model' => sanitize_text_field((string)($event['model'] ?? '')),
            'usage' => $usage,
        ];

        self::ensure_usage_table();
        if (self::usage_table_ready()) {
            global $wpdb;
            $table = self::usage_table_name();
            $ts = (int)$entry['ts'];

            $wpdb->insert($table, [
                'event_ts' => $ts,
                'created_at' => gmdate('Y-m-d H:i:s', $ts),
                'label' => (string)$entry['label'],
                'type' => (string)$entry['type'],
                'model' => (string)$entry['model'],
                'prompt_tokens' => (int)($usage['prompt_tokens'] ?? 0),
                'output_tokens' => (int)($usage['output_tokens'] ?? 0),
                'total_tokens' => (int)($usage['total_tokens'] ?? 0),
                'tool_tokens' => (int)($usage['tool_tokens'] ?? 0),
                'thought_tokens' => (int)($usage['thought_tokens'] ?? 0),
                'cached_tokens' => (int)($usage['cached_tokens'] ?? 0),
                'payload' => wp_json_encode(['usage' => $usage]),
            ], ['%d','%s','%s','%s','%s','%d','%d','%d','%d','%d','%d','%s']);

            $wpdb->query("DELETE FROM {$table} WHERE id NOT IN (SELECT id FROM (SELECT id FROM {$table} ORDER BY id DESC LIMIT {$keep_last}) t)");
            return;
        }

        // Fallback legacy option.
        $key = 'aiblogger_usage_log';
        $log = get_option($key, []);
        if (!is_array($log)) $log = [];
        $log[] = $entry;
        if (count($log) > $keep_last) {
            $log = array_slice($log, -$keep_last);
        }
        update_option($key, $log, false);
    }

    /**
     * Devuelve eventos de uso recientes (mas recientes primero).
     */
    public static function get_usage_log(int $limit = 50): array {
        return self::get_usage_log_range(null, null, $limit);
    }

    public static function get_usage_log_range(?int $from_ts = null, ?int $to_ts = null, int $limit = 500, array $types = []): array {
        $limit = max(1, min(5000, (int)$limit));

        self::ensure_usage_table();
        if (self::usage_table_ready()) {
            global $wpdb;
            $table = self::usage_table_name();
            $where = ['1=1'];

            if ($from_ts) {
                $where[] = $wpdb->prepare('event_ts >= %d', (int)$from_ts);
            }
            if ($to_ts) {
                $where[] = $wpdb->prepare('event_ts <= %d', (int)$to_ts);
            }

            $types = array_values(array_filter(array_map('sanitize_key', $types)));
            if ($types) {
                $quoted = array_map(function($t) use ($wpdb){ return $wpdb->prepare('%s', $t); }, $types);
                $where[] = 'type IN (' . implode(',', $quoted) . ')';
            }

            $sql = "SELECT event_ts,label,type,model,prompt_tokens,output_tokens,total_tokens,tool_tokens,thought_tokens,cached_tokens,payload
                    FROM {$table}
                    WHERE " . implode(' AND ', $where) . "
                    ORDER BY event_ts DESC
                    LIMIT " . (int)$limit;

            $rows = $wpdb->get_results($sql, ARRAY_A);
            if (is_array($rows)) {
                $out = [];
                foreach ($rows as $r) {
                    $out[] = [
                        'ts' => (int)($r['event_ts'] ?? 0),
                        'label' => (string)($r['label'] ?? ''),
                        'type' => (string)($r['type'] ?? 'extra'),
                        'model' => (string)($r['model'] ?? ''),
                        'usage' => [
                            'prompt_tokens' => (int)($r['prompt_tokens'] ?? 0),
                            'output_tokens' => (int)($r['output_tokens'] ?? 0),
                            'total_tokens' => (int)($r['total_tokens'] ?? 0),
                            'tool_tokens' => (int)($r['tool_tokens'] ?? 0),
                            'thought_tokens' => (int)($r['thought_tokens'] ?? 0),
                            'cached_tokens' => (int)($r['cached_tokens'] ?? 0),
                        ],
                    ];
                }
                return $out;
            }
        }

        // Legacy fallback
        $log = get_option('aiblogger_usage_log', []);
        if (!is_array($log)) return [];

        $out = [];
        $types = array_values(array_filter(array_map('sanitize_key', $types)));
        foreach (array_reverse($log) as $e) {
            if (!is_array($e)) continue;
            $ts = (int)($e['ts'] ?? 0);
            if ($from_ts && $ts < $from_ts) continue;
            if ($to_ts && $ts > $to_ts) continue;
            if ($types) {
                $t = sanitize_key((string)($e['type'] ?? ''));
                if (!in_array($t, $types, true)) continue;
            }
            $out[] = $e;
            if (count($out) >= $limit) break;
        }
        return $out;
    }

    /**
     * Agrega tokens a partir de un listado de eventos.
     */
    public static function aggregate_usage_log(array $log): array {
        if (!is_array($log) || !$log) return self::aggregate_usage([]);
        $calls = [];
        foreach ($log as $e) {
            if (!is_array($e)) continue;
            $calls[] = [
                'type' => (string)($e['type'] ?? 'extra'),
                'usage' => is_array($e['usage'] ?? null) ? $e['usage'] : [],
            ];
        }
        return self::aggregate_usage($calls);
    }

    public static function usage_totals_between(int $from_ts, int $to_ts, array $types = []): int {
        $from_ts = max(0, $from_ts);
        $to_ts = max($from_ts, $to_ts);

        self::ensure_usage_table();
        if (!self::usage_table_ready()) return 0;

        global $wpdb;
        $table = self::usage_table_name();

        $where = ['event_ts >= %d', 'event_ts <= %d'];
        $params = [$from_ts, $to_ts];

        $types = array_values(array_filter(array_map('sanitize_key', $types)));
        if ($types) {
            $placeholders = implode(',', array_fill(0, count($types), '%s'));
            $where[] = "type IN ({$placeholders})";
            $params = array_merge($params, $types);
        }

        $sql = "SELECT COALESCE(SUM(total_tokens),0) FROM {$table} WHERE " . implode(' AND ', $where);
        $prepared = $wpdb->prepare($sql, $params);
        return (int)$wpdb->get_var($prepared);
    }

    public static function site_token_budget_status(): array {
        $opts = self::get_options();

        $daily_limit = max(0, (int)($opts['tokens_daily_limit'] ?? 0));
        $monthly_limit = max(0, (int)($opts['tokens_monthly_limit'] ?? 0));
        $mode = in_array((string)($opts['tokens_limit_mode'] ?? 'warn'), ['warn', 'block'], true) ? (string)$opts['tokens_limit_mode'] : 'warn';

        $tz = wp_timezone();
        $now_dt = new DateTimeImmutable('now', $tz);
        $now = $now_dt->getTimestamp();
        $day_start = $now_dt->setTime(0, 0, 0)->getTimestamp();
        $month_start = $now_dt->setDate((int)$now_dt->format('Y'), (int)$now_dt->format('m'), 1)->setTime(0, 0, 0)->getTimestamp();

        $used_daily = self::usage_totals_between((int)$day_start, $now);
        $used_monthly = self::usage_totals_between((int)$month_start, $now);

        $daily_exceeded = ($daily_limit > 0 && $used_daily >= $daily_limit);
        $monthly_exceeded = ($monthly_limit > 0 && $used_monthly >= $monthly_limit);

        return [
            'mode' => $mode,
            'daily_limit' => $daily_limit,
            'monthly_limit' => $monthly_limit,
            'used_daily' => $used_daily,
            'used_monthly' => $used_monthly,
            'daily_exceeded' => $daily_exceeded,
            'monthly_exceeded' => $monthly_exceeded,
            'exceeded' => ($daily_exceeded || $monthly_exceeded),
        ];
    }


    public static function backfill_post_usage_events(int $limit = 500): void {
        $limit = max(1, min(5000, (int)$limit));

        self::ensure_usage_table();
        if (!self::usage_table_ready()) return;

        $q = new WP_Query([
            'post_type' => 'any',
            'posts_per_page' => $limit,
            'meta_key' => '_aiblogger_metrics',
            'orderby' => 'date',
            'order' => 'DESC',
            'fields' => 'ids',
            'no_found_rows' => true,
        ]);

        if (!$q->have_posts()) return;

        foreach ((array)$q->posts as $pid) {
            $pid = (int)$pid;
            if ($pid <= 0) continue;
            if (get_post_meta($pid, '_aiblogger_usage_logged', true)) continue;

            $m = get_post_meta($pid, '_aiblogger_metrics', true);
            if (!is_array($m)) continue;

            self::log_usage_event([
                'label' => 'Backfill post #' . $pid,
                'type'  => 'post',
                'model' => trim((string)($m['text_model'] ?? '') . ' / ' . (string)($m['image_model'] ?? ''), ' /'),
                'usage' => [
                    'prompt_tokens' => (int)($m['prompt_tokens'] ?? 0),
                    'output_tokens' => (int)($m['output_tokens'] ?? 0),
                    'total_tokens' => (int)($m['total_tokens'] ?? 0),
                    'tool_tokens' => (int)($m['tool_tokens'] ?? 0),
                    'thought_tokens' => (int)($m['thought_tokens'] ?? 0),
                    'cached_tokens' => (int)($m['cached_tokens'] ?? 0),
                ],
            ], 200000);

            update_post_meta($pid, '_aiblogger_usage_logged', 1);
        }
    }
    public static function parse_media_ids($raw, int $limit = 10): array {
        $limit = max(0, min(50, $limit));
        if ($limit === 0) return [];

        if (is_array($raw)) {
            $vals = $raw;
        } else {
            $vals = preg_split('/[^0-9]+/', (string)$raw);
        }

        $ids = [];
        foreach ((array)$vals as $v) {
            $id = (int)$v;
            if ($id <= 0) continue;
            $ids[] = $id;
        }

        $ids = array_values(array_unique($ids));
        return array_slice($ids, 0, $limit);
    }

    public static function media_context_from_ids(array $media_ids, int $max_files = 8, int $max_chars = 16000): string {
        $max_files = max(1, min(20, $max_files));
        $max_chars = max(1000, min(80000, $max_chars));

        $chunks = [];
        $total = 0;

        foreach (array_slice($media_ids, 0, $max_files) as $id) {
            $id = (int)$id;
            if ($id <= 0) continue;

            $att = get_post($id);
            if (!$att || $att->post_type !== 'attachment') continue;

            $file = get_attached_file($id);
            $url = wp_get_attachment_url($id) ?: '';
            $name = $file ? basename((string)$file) : ('attachment-' . $id);
            $ext = strtolower(pathinfo((string)$name, PATHINFO_EXTENSION));

            $text = '';
            if ($file && is_readable($file)) {
                $text = self::extract_attachment_text((string)$file, $ext);
            }

            if ($text !== '') {
                $chunk = "[Documento: {$name}]\n{$text}";
            } else {
                $chunk = "[Documento adjunto: {$name}]";
                if ($url) $chunk .= "\nURL: {$url}";
                if (in_array($ext, ['pdf','doc','docx'], true)) {
                    $chunk .= "\n(Referencia incluida; no se pudo extraer texto legible de este archivo.)";
                }
            }

            $remain = $max_chars - $total;
            if ($remain <= 0) break;
            if (mb_strlen($chunk) > $remain) {
                $chunk = mb_substr($chunk, 0, $remain);
            }

            $chunks[] = $chunk;
            $total += mb_strlen($chunk);
            if ($total >= $max_chars) break;
        }

        return trim(implode("\n\n", $chunks));
    }


    private static function extract_attachment_text(string $file, string $ext): string {
        $ext = strtolower(trim($ext));

        if (!is_readable($file)) return '';

        if (in_array($ext, ['txt','md','csv','json','log','xml','html'], true)) {
            $fsize = @filesize($file);
            if (!is_int($fsize) || $fsize <= 2 * 1024 * 1024) {
                return self::safe_excerpt((string)file_get_contents($file), 5000);
            }
            return '';
        }

        if ($ext === 'docx') {
            return self::extract_docx_text($file);
        }

        if ($ext === 'pdf') {
            return self::extract_pdf_text($file);
        }

        if ($ext === 'doc') {
            return self::extract_doc_binary_text($file);
        }

        return '';
    }

    private static function extract_docx_text(string $file): string {
        if (!class_exists('ZipArchive')) return '';

        $zip = new ZipArchive();
        if ($zip->open($file) !== true) return '';

        $xml = $zip->getFromName('word/document.xml');
        $zip->close();
        if (!is_string($xml) || $xml === '') return '';

        $xml = str_replace(['</w:p>', '</w:tr>'], ["\n", "\n"], $xml);
        $text = strip_tags($xml);
        $text = preg_replace('/\s+/', ' ', (string)$text);
        return self::safe_excerpt(trim((string)$text), 5000);
    }

    private static function extract_pdf_text(string $file): string {
        $raw = @file_get_contents($file);
        if (!is_string($raw) || $raw === '') return '';

        $chunks = [];
        if (preg_match_all('/stream\r?\n(.*?)\r?\nendstream/s', $raw, $m)) {
            foreach ($m[1] as $stream) {
                $decoded = @gzuncompress($stream);
                if (!is_string($decoded) || $decoded === '') {
                    $decoded = @gzdecode($stream);
                }
                if (!is_string($decoded) || $decoded === '') {
                    $decoded = $stream;
                }

                if (preg_match_all('/\(([^\)]{1,400})\)\s*T[Jj]/s', $decoded, $tm)) {
                    foreach ($tm[1] as $t) {
                        $chunks[] = stripcslashes($t);
                    }
                }
            }
        }

        if (!$chunks) {
            $plain = preg_replace('/[^\x20-\x7E\x0A\x0D\x09]+/', ' ', $raw);
            $plain = preg_replace('/\s+/', ' ', (string)$plain);
            return self::safe_excerpt(trim((string)$plain), 2000);
        }

        $text = implode("\n", $chunks);
        $text = preg_replace('/\s+/', ' ', (string)$text);
        return self::safe_excerpt(trim((string)$text), 5000);
    }

    private static function extract_doc_binary_text(string $file): string {
        $raw = @file_get_contents($file);
        if (!is_string($raw) || $raw === '') return '';

        $text = preg_replace('/[^\x20-\x7E\x0A\x0D\x09]+/', ' ', $raw);
        $text = preg_replace('/\s+/', ' ', (string)$text);
        return self::safe_excerpt(trim((string)$text), 2500);
    }

