ƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â.
     */
    public static function extract_urls_from_text(string $text, int $limit = 10): array {
        $limit = max(0, min(50, $limit));
        if ($limit === 0) return [];

        $text = (string)$text;
        if ($text === '') return [];

        $found = [];

        // Captura http(s)://...
        if (preg_match_all('~https?://[^\s<>"]+~i', $text, $m)) {
            foreach ($m[0] as $u) {
                $u = trim((string)$u);
                $u = rtrim($u, '.,;:)\]\}');
                $u = esc_url_raw($u);
                if ($u) $found[] = $u;
            }
        }

        // Captura www.... (sin esquema)
        if (preg_match_all('~\bwww\.[^\s<>"]+~i', $text, $m2)) {
            foreach ($m2[0] as $u) {
                $u = trim((string)$u);
                $u = rtrim($u, '.,;:)\]\}');
                $u = 'https://' . ltrim($u, '/');
                $u = esc_url_raw($u);
                if ($u) $found[] = $u;
            }
        }

        $found = array_values(array_unique($found));
        return array_slice($found, 0, $limit);
    }

