    public static function external_link_candidates(string $topic, array $ref_infos, array $opts, int $limit = 8): array {
        $limit = max(0, min(20, $limit));
        if ($limit === 0) return [];

        $cands = [];
        if (is_array($ref_infos)) {
            foreach ($ref_infos as $r) {
                if (empty($r['url'])) continue;
                $u = (string)$r['url'];
                $cands[] = [
                    'title' => (string)($r['title'] ?? (parse_url($u, PHP_URL_HOST) ?: $u)),
                    'url' => $u,
                ];
            }
        }

        // Dedup
        $seen = [];
        $out = [];
        foreach ($cands as $c) {
            $u = (string)($c['url'] ?? '');
            if (!$u) continue;
            if (isset($seen[$u])) continue;
            $seen[$u] = true;
            $out[] = [
                'title' => (string)($c['title'] ?? $u),
                'url' => $u,
            ];
            if (count($out) >= $limit) break;
        }
        return $out;
    }
